    if n < 2:
        raise ValueError("N deve essere almeno 2")
    lati = fibonacci(n)
    quadrati = [Quadrato(1, 0, 0), Quadrato(1, 1, 0)]
    # Il centro comune produce il semicerchio nei due quadrati unitari.
